// Write a function in Java to compute the standard deviation of an array of real numbers. The function should also handle cases where the array may contain mis...
// Furthermore, the function should have a time complexity of O(n), where n is the number of elements in the input array. The space complexity should be O(1), m...
public static int computeStandardDeviation(double[] array) {

target:
    int n = array.length;
    int count = 0;
    double sum = 0.0;
    double squaredSum = 0.0;

    for (double num : array) {
        if (!Double.isNaN(num)) {
            count++;
            sum += num;
            squaredSum += num * num;
        }
    }

    if (count == 0) {
        return 0;
    }

    double mean = sum / count;
    double variance = (squaredSum - count * mean * mean) / count;
    double standardDeviation = Math.sqrt(variance);

    return (int) Math.round(standardDeviation);
}

