    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        if (c == ' ') {
            if (camelCaseBuilder.length() > 0) {
                String word = camelCaseBuilder.toString();
                wordCountMap.put(word, wordCountMap.getOrDefault(word, 0) + 1);
                camelCaseBuilder.setLength(0);
            }

            isFirstWord = true;
        } else {
            if (isFirstWord) {
                camelCaseBuilder.append(Character.toLowerCase(c));
                isFirstWord = false;
            } else {
                camelCaseBuilder.append(Character.toUpperCase(c));
            }
        }
    }

    if (camelCaseBuilder.length() > 0) {
        String word = camelCaseBuilder.toString();
        wordCountMap.put(word, wordCountMap.getOrDefault(word, 0) + 1);
    }

    return wordCountMap;
}

