    PriorityQueue<Point> queue = new PriorityQueue<>((a, b) -> a.sum - b.sum);
    queue.offer(new Point(0, 0, dp[0][0]));

    List<Integer> result = new ArrayList<>();
    int[][] directions = new int[][]{{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

    while(!queue.isEmpty() && result.size() < k) {
        Point cur = queue.poll();
        result.add(cur.sum);

        for(int[] dir : directions) {
            int ni = cur.i + dir[0];
            int nj = cur.j + dir[1];

            if(ni >= 0 && ni < n && nj >= 0 && nj < n) {
                int newSum = cur.sum + grid[ni][nj];
                if(newSum < dp[ni][nj]) {
                    dp[ni][nj] = newSum;
                    queue.offer(new Point(ni, nj, newSum));
                }
            }
        }
    }
    return result;
}

