// Find the square root of a given number using only bitwise operators and without using any built-in mathematical functions or libraries.
public static int squareRoot(int num) {

target:
    if (num < 0) {
        throw new IllegalArgumentException("Number cannot be negative");
    }

    if (num == 0 || num == 1) {
        return num;
    }

    int start = 1;
    int end = num;
    int result = 0;

    while (start <= end) {
        int mid = (start + end) / 2;

        // Check if mid*mid is equal to num
        if (mid == num / mid) {
            return mid;
        }

        // If mid*mid is less than or equal to num, update the result and move to the right half
        if (mid <= num / mid) {
            start = mid + 1;
            result = mid;
        }
        // If mid*mid is greater than num, move to the left half
        else {
            end = mid - 1;
        }
    }

    return result;
}

