    for (String value : values) {
        // Remove leading and trailing whitespaces from each value
        value = value.trim();

        // Check if the value consists only of lowercase letters
        if (value.matches("[a-z]+")) {
            // Add the lowercase value to the array list
            lowercaseValues.add(value);
        }
    }

    // Convert the array list to an array of strings
