    int low = 0;
    int high = arr.length - 1;
    int lastOccurrence = -1;

    while (low <= high) {
        int mid = low + (high - low) / 2;

        if (arr[mid] == searchValue) {
            lastOccurrence = mid;
            low = mid + 1;
        } else if (arr[mid] < searchValue) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return lastOccurrence;
}

