    int n = grid.length;
    int[][] dp = new int[n + 1][n + 1];
    List<List<int[]>> dpDirection = new ArrayList<>();
    for (int i = 0; i <= n; i++) {
        dpDirection.add(new ArrayList<>(Collections.nCopies(n + 1, new ArrayList<>())));
    }

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            int maxSum = Math.max(dp[i - 1][j], dp[i][j - 1]);
            int[] dirIndex = dp[i - 1][j] > dp[i][j - 1] ? new int[]{i - 1, j} : new int[]{i, j - 1};
            dp[i][j] = maxSum + grid[i - 1][j - 1];
            dpDirection.get(i).set(j, new ArrayList<>(dpDirection.get(dirIndex[0]).get(dirIndex[1])));
            dpDirection.get(i).get(j).add(new int[]{i - 1, j - 1});
        }
    }

    List<int[]> paths = dpDirection.get(n).get(n);
    paths.sort((a, b) -> grid[b[0]][b[1]] - grid[a[0]][a[1]]);

    List<Integer> result = new ArrayList<>();
    int min = Math.min(k, paths.size());
    for (int i = 0; i < min; i++) {
        result.add(grid[paths.get(i)[0]][paths.get(i)[1]]);
    }
    return result;
}

