                currentNumber -= increment;
            } else {
                currentNumber += increment;
            }
        }

        // Reverse the number sequence for alternate rows
        if (i % 2 == 0) {
            currentNumber += increment;
        } else {
            currentNumber -= increment;
        }

        totalSum += rowSum;
        System.out.println();
    }

    System.out.println("\nTotal Sum: " + totalSum);
}

