public int flipgame(int[] fronts, int[] backs) {

target:
    HashSet<Integer> noFav = new HashSet<>();
    PriorityQueue<Integer> possible = new PriorityQueue<>();
    for (int i = 0; i < fronts.length; ++i) {
        if (fronts[i] == backs[i]) {
            noFav.add(fronts[i]);
        }else{
            possible.offer(fronts[i]);
            possible.offer(backs[i]);
        }
    }
    while (!possible.isEmpty()) {
        int cur = possible.poll();
        if (!noFav.contains(cur)) return cur;
    }
    return 0;
}

