public static int computeStandardDeviation(float[] data) {

target:
    int n = 0;
    float sum = 0;
    float sumOfSquares = 0;

    for (float num : data) {
        if (!Float.isNaN(num)) {
            n++;
            sum += num;
            sumOfSquares += num * num;
        }
    }

    if (n == 0) {
        return 0; // If all values are missing (NaN), return 0 as standard deviation
    }

    float mean = sum / n;
    float variance = (sumOfSquares / n) - (mean * mean);
    float standardDeviation = (float) Math.sqrt(variance);

    return Math.round(standardDeviation);
}

