        char c = strList.charAt(i);
        // If it's an opening bracket, increase the counter
        if(c == '(') depth++;
        // If it's a closing bracket, decrease the counter
        else if(c == ')') depth--;
        // If at any point the counter is negative, we have a closing bracket without an opening pair
        if(depth < 0) return "No";
    }

    // If at the end the counter is not 0, we have opening brackets without closing pairs
    if(depth != 0) return "No";

    // If all checks are passed, the parentheses in the string are balanced
    return "Yes";
}

