    while (l < r) {
        if (!Character.isAlphabetic(charArray[l]))
            l++;
        else if(!Character.isAlphabetic(charArray[r]))
            r--;
        else {
            char tmp = charArray[l];
            charArray[l] = charArray[r];
            charArray[r] = tmp;
        l++;
        r--;
        }
    }
    str = new String(charArray);
    System.out.println("Reversed string is " + str);
}

