public static String combine(String str1, String str2) {

target:
    StringBuilder combined = new StringBuilder();

    // Append the first string
    combined.append(str1);

    // Calculate the remaining capacity for the second string
    int remainingCapacity = 200 - str1.length();

    // If the remaining capacity is negative, set it to 0
    remainingCapacity = Math.max(remainingCapacity, 0);

    // Append the second string, up to the remaining capacity
    combined.append(str2.substring(0, Math.min(str2.length(), remainingCapacity)));

    return combined.toString();
}

