// Encodes the input string by performing cyclic shift on groups of four characters.
// It includes numerics, punctuations and Unicode characters.
public String encodeCyclic(String s) {

target:
    StringBuilder result = new StringBuilder();  // to build the result string

    for (int i = 0; i < s.length(); i++) {
        // Get Unicode code point of the character
        int charCode = s.charAt(i);

        // Shift the code point
        charCode = charCode + (i % 4) + 1;

        // convert back to char, handling overflow with modulus operation
        result.append((char) (charCode % 65536));
    }
    return result.toString();
}

