                array[j] = array[j+1];
                array[j+1] = temp;
                swapped = true;
            }
        }

        if (!swapped) {
            break;
        }

        // Print the sorted array after each pass
        System.out.print("Pass " + (i+1) + ": ");
        printArray(array);
    }
}

