    String input = scan.nextLine();  // E.g., Apple 1, Orange 2, Banana 3
    String[] items = input.split(", ");
    Map<String, Integer> map = new HashMap<>();
    for(String item : items) {
        String[] keyValuePair = item.split(" ");
        map.put(keyValuePair[0], Integer.parseInt(keyValuePair[1]));
    }
    System.out.println(map);  // Output: {Apple=1, Orange=2, Banana=3}
}

