// In addition to printing the array in a spiral order, modify the method to also return the sum of all the elements in the array.
public static int printSpiral(int[][] array) {

target:
    int sum = 0;
    int rows = array.length;
    int cols = array[0].length;
    int startRow = 0, startCol = 0;

    while (startRow < rows && startCol < cols) {
        // Print the first row from the remaining rows
        for (int i = startCol; i < cols; i++) {
            System.out.print(array[startRow][i] + " ");
            sum += array[startRow][i];
        }
        startRow++;

        // Print the last column from the remaining columns
        for (int i = startRow; i < rows; i++) {
            System.out.print(array[i][cols - 1] + " ");
            sum += array[i][cols - 1];
        }
        cols--;

        // Print the last row from the remaining rows
        if (startRow < rows) {
            for (int i = cols - 1; i >= startCol; i--) {
                System.out.print(array[rows - 1][i] + " ");
                sum += array[rows - 1][i];
            }
            rows--;
        }

        // Print the first column from the remaining columns
        if (startCol < cols) {
            for (int i = rows - 1; i >= startRow; i--) {
                System.out.print(array[i][startCol] + " ");
                sum += array[i][startCol];
            }
            startCol++;
        }
    }

    return sum;
}

