    resizedImage.getGraphics().drawImage(originalImage, 0, 0, targetWidth, targetHeight, null);

    // Apply grayscale filter
    for (int y = 0; y < resizedImage.getHeight(); y++) {
        for (int x = 0; x < resizedImage.getWidth(); x++) {
            int rgb = resizedImage.getRGB(x, y);
            int r = (rgb >> 16) & 0xFF;
            int g = (rgb >> 8) & 0xFF;
            int b = (rgb & 0xFF);
            int gray = (r + g + b) / 3;
            int grayRgb = (gray << 16) | (gray << 8) | gray;
            resizedImage.setRGB(x, y, grayRgb);
        }
    }

    // Save the processed image to a new file
    File processedFile = new File("processed_image.png");
    ImageIO.write(resizedImage, "png", processedFile);

    return processedFile;
}

