        String birthDate = document.getElementsByTagName("birthDate").item(i).getTextContent();
        String position = document.getElementsByTagName("position").item(i).getTextContent();
        String department = document.getElementsByTagName("department").item(i).getTextContent();
        String skill = document.getElementsByTagName("skill").item(i).getTextContent();
        String hobby = document.getElementsByTagName("hobby").item(i).getTextContent();

        printer.printRecord(firstName, lastName, birthDate, position, department, skill, hobby);
    }

    printer.flush();
    out.close();
