    // Count the number of occurrences of each character type
    int uppercaseCount = 0;
    int lowercaseCount = 0;
    int specialCharCount = 0;
    int digitCount = 0;

    for (char c : password.toCharArray()) {
        if (Character.isUpperCase(c)) {
            uppercaseCount++;
        } else if (Character.isLowerCase(c)) {
            lowercaseCount++;
        } else if (Character.isDigit(c)) {
            digitCount++;
        } else {
            specialCharCount++;
        }
    }

    // Check if the counts meet the complexity requirements
    return uppercaseCount >= 2 && lowercaseCount >= 2 && specialCharCount >= 2 && digitCount >= 2;
}

