        q.add(pq.poll());
        int next = (pq.isEmpty()) ? -1 : pq.poll();
        if (next != -1) pq.add(next);
        m.put(q.peek(), count);
        count++;
        if (!pq.isEmpty()) q.add(q.poll());
    }
