// However, the program should handle negative numbers, decimal numbers, and scientific notation as well.
// For example, for the input -3.45e2, the program should output -12.5.
public static void main(String[] args) {

target:
    Scanner scanner = new Scanner(System.in);
    System.out.print("Enter a number: ");
    String input = scanner.nextLine();
    double number = Double.parseDouble(input);
    double sum = 0;

    // Check if the number is negative
    boolean isNegative = false;
    if (number < 0) {
        isNegative = true;
        number = Math.abs(number);
    }

    // Extract the integer part
    int integerPart = (int) number;

    // Add the digits of the integer part
    while (integerPart != 0) {
        int digit = integerPart % 10;
        sum += digit;
        integerPart /= 10;
    }

    // Extract the decimal part
    double decimalPart = number - integerPart;

    // Add the digits of the decimal part
    while (decimalPart != 0) {
        decimalPart *= 10;
        int digit = (int) decimalPart;
        sum += digit;
        decimalPart -= digit;
    }

    // Print the sum
    if (isNegative) {
        sum *= -1;
    }
    System.out.println("Sum of digits: " + sum);
}

