    int count = 0;
    for (int num : arr) {
        if (num % 3 != 0 || num % 2 != 0) {
            count++;
        }
    }
    int[] newArr = new int[count];
    int index = 0;
    for (int num : arr) {
        if (num % 3 != 0 || num % 2 != 0) {
            newArr[index++] = num;
        }
    }

    // Step 2: Sort the remaining numbers in ascending order
    Arrays.sort(newArr);

    return newArr;
}

