    int[] L = new int[n1];
    int[] R = new int[n2];

    for (int i = 0; i < n1; i++) {
      L[i] = arr[left + i];
    }
    for (int j = 0; j < n2; j++) {
      R[j] = arr[mid + 1 + j];
