    Map<Integer, List<List<Integer>>> groups = new HashMap<>(); // group by counts
    for (Map.Entry<Integer, Integer> entry : count.entrySet()) {
        int key = entry.getValue();
        if (!groups.containsKey(key)) {
            groups.put(key, new ArrayList<>());
        }
        groups.get(key).add(Collections.nCopies(key, entry.getKey()));
    }

    List<List<Integer>> res = new ArrayList<>(); // gather results
    for (List<List<Integer>> group : groups.values()) {
        if (group.size() == 1) res.addAll(group);
    }

    return res;
}

