public static String reverseAlphabetical(String input) {

target:
    char[] chars = input.toCharArray();
    int left = 0;
    int right = chars.length - 1;

    while (left < right) {
        // Skip non-alphabetical characters from the left
        while (left < right && !Character.isLetter(chars[left])) {
            left++;
        }

        // Skip non-alphabetical characters from the right
        while (left < right && !Character.isLetter(chars[right])) {
            right--;
        }

        // Reverse the alphabetical characters
        if (Character.isLetter(chars[left]) && Character.isLetter(chars[right])) {
            char temp = chars[left];
            chars[left] = chars[right];
            chars[right] = temp;
        }

        left++;
        right--;
    }

    return new String(chars);
}

