    while (left <= right) {
        int mid = left + (right - left) / 2;

        if (arr[mid] == target) {
            // Check if the target element is the first occurrence
            while (mid > 0 && arr[mid - 1] == target) {
                mid--;
            }
            return mid;
        }

        if (arr[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    // Element not found
    return -1;
}

