    if (n < 0) {
        throw new IllegalArgumentException("The parameter n must be a non-negative integer.");
    }
    if (offset < 0) {
        throw new IllegalArgumentException("The offset must be a non-negative integer.");
    }

    // Create an array to store the calculated Fibonacci sequence. Size = n + offset + 1
    int[] fibSeq = new int[n + offset + 1];

    // Initialize the first `offset` elements to 0
    for (int i = 0; i < offset; i++) {
        fibSeq[i] = 0;
    }

    // Initialize offset to offset+6 elements
    int[] initSeq = new int[]{0, 1, 1, 2, 4, 7};
    for (int i = 0; i < Math.min(initSeq.length, n + 1); i++) {
        fibSeq[i + offset] = initSeq[i];
    }

    // Calculate rest of the elements in fibSeq array according to the modified Fibonacci rule.
    for (int i = offset + 6; i < n + offset + 1; i++) {
        fibSeq[i] = fibSeq[i - 1] + fibSeq[i - 3] + fibSeq[i - 4] + fibSeq[i - 6];
    }

    // Return the n+offset element of the sequence
    return fibSeq[n + offset];
}

