    int length;
    // Find the length of the list
    for (length = 0; fast.next != null; length++) {
        fast = fast.next;
    }

    // Find the node before the rotation point
    for (int j = length - k % length; j > 0; j--) {
        slow = slow.next;
    }

    // Connect the end of the list to the front, break the list at the rotation point and return the new head
    fast.next = dummy.next;
    dummy.next = slow.next;
    slow.next = null;

    return dummy.next;
}

